-- ----------------------------
-- Table structure for zp_admin
-- ----------------------------
DROP TABLE IF EXISTS `zp_admin`;
CREATE TABLE `zp_admin` (
    `id` tinyint(4) NOT NULL AUTO_INCREMENT COMMENT '管理员ID',
    `admin_id` int(10) unsigned DEFAULT '0' COMMENT '所属上级代理ID',
    `group_id` tinyint(5) unsigned DEFAULT '0' COMMENT '所属用户组ID',
    `username` varchar(20) NOT NULL COMMENT '管理员用户名',
    `mobile` varchar(11) DEFAULT NULL COMMENT '电话号码',
    `email` varchar(30) DEFAULT NULL COMMENT '邮箱',
    `password` varchar(32) NOT NULL COMMENT '管理员密码',
    `salt` varchar(6) DEFAULT NULL COMMENT '盐值',
    `token` varchar(50) DEFAULT NULL COMMENT 'token',
    `avatar` varchar(200) DEFAULT NULL COMMENT '头像地址',
    `qrcode` varchar(128) DEFAULT NULL COMMENT '微信二维码',
    `wechat` varchar(64) DEFAULT NULL COMMENT '微信号',
    `realname` varchar(10) DEFAULT NULL COMMENT '真实姓名',
    `balance` decimal(16,4) unsigned DEFAULT '0.0000' COMMENT '账户余额',
    `min_cash` decimal(11,2) unsigned DEFAULT '100.00' COMMENT '最低提现',
    `min_take` decimal(11,2) unsigned DEFAULT '5.00' COMMENT '最低抽成比例，5.00%',
    `min_pub` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '资源最低发布金额',
    `dis_pub` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '资源最低发布原价',
    `cash_fee` decimal(11,2) unsigned DEFAULT '10.00' COMMENT '提现手续费比例,10%',
    `auto_spread` tinyint(1) unsigned DEFAULT '1' COMMENT '是否自动推广:1手动，2自动',
    `kammi_type` tinyint(1) unsigned DEFAULT '0' COMMENT '卡密权限类型，0禁止，1创建',
    `is_ad` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否开启广告，1开启',
    `take_num` int(10) unsigned DEFAULT '5' COMMENT '扣量间隔，5表示，每5次扣一次，相当于20%',
    `exp_time` int(10) unsigned DEFAULT '0' COMMENT '过期时间',
    `short_id` int(11) unsigned DEFAULT '1' COMMENT '短链接通道ID',
    `check_id` int(11) unsigned DEFAULT '0' COMMENT '检测通道ID',
    `entry_url` varchar(128) DEFAULT NULL COMMENT '防封入口（主要是微信）',
    `view_id` int(10) unsigned DEFAULT '0' COMMENT '默认模板ID-首页布局ID',
    `loginfail` int(10) unsigned DEFAULT '0' COMMENT '登录失败次数',
    `master_token` varchar(64) DEFAULT NULL COMMENT '主资源库接口TOKEN',
    `api_token` varchar(100) DEFAULT NULL COMMENT '资源市场token',
    `logtime` int(10) unsigned DEFAULT '0' COMMENT '登录时间',
    `logip` varchar(20) DEFAULT NULL COMMENT '登录IP',
    `status` tinyint(2) unsigned DEFAULT '1' COMMENT '审核状态,1正常，0禁用',
    `ctime` int(11) unsigned DEFAULT '0' COMMENT '添加时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `idx_username` (`username`) USING BTREE,
    KEY `idx_balace` (`id`,`balance`) USING BTREE,
    KEY `idx_use` (`id`),
    KEY `idx_group_id` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='管理员表';

-- ----------------------------
-- Table structure for zp_admin_bill
-- ----------------------------
DROP TABLE IF EXISTS `zp_admin_bill`;
CREATE TABLE `zp_admin_bill` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
     `type` tinyint(3) unsigned DEFAULT '0' COMMENT '类型，1资源收益，2VIP收益，3分成，4扣量',
     `mode` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '模式，1：增加，2：减少',
     `before` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '操作前余额',
     `money` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '金额',
     `after` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '操作后余额',
     `remark` varchar(200) DEFAULT NULL COMMENT '备注',
     `order_id` int(10) unsigned DEFAULT '0' COMMENT '业务ID',
     `uid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
     `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
     PRIMARY KEY (`id`),
     KEY `idx_user` (`uid`),
     KEY `idx_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='余额操作日志';

-- ----------------------------
-- Table structure for zp_admin_log
-- ----------------------------
DROP TABLE IF EXISTS `zp_admin_log`;
CREATE TABLE `zp_admin_log` (
    `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
    `content` text COLLATE utf8mb4_unicode_ci,
    `remark` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作描述',
    `url` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问路径',
    `ua` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '浏览器特征',
    `ip` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作IP',
    `uid` int(10) unsigned DEFAULT '0' COMMENT '操作员ID',
    `ctime` int(11) unsigned DEFAULT '0' COMMENT '记录时间',
    PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统日志表';

-- ----------------------------
-- Table structure for zp_admin_site
-- ----------------------------
DROP TABLE IF EXISTS `zp_admin_site`;
CREATE TABLE `zp_admin_site` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
     `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
     `webname` varchar(64) DEFAULT NULL COMMENT '站点名称',
     `is_ssl` tinyint(3) unsigned DEFAULT '0' COMMENT '是否配置了SSL，1为是',
     `sub_type` tinyint(2) unsigned DEFAULT '0' COMMENT '域名类型，0，二级域名，1一级域名',
     `domain` varchar(64) DEFAULT NULL COMMENT '一级域名',
     `sub_prefix` varchar(32) DEFAULT NULL COMMENT '二级域名前缀',
     `base_domain` varchar(48) DEFAULT NULL COMMENT '二级根域名',
     `entry_url` varchar(256) DEFAULT NULL COMMENT '防封链接入口',
     `wechat` varchar(48) DEFAULT NULL COMMENT '微信号',
     `qrcode` varchar(128) DEFAULT NULL COMMENT '二维码',
     `realname` varchar(32) DEFAULT NULL COMMENT '联系人',
     `mobile` varchar(48) DEFAULT NULL COMMENT '联系电话',
     `utime` int(10) unsigned DEFAULT '0' COMMENT '联系时间',
     `ctime` int(10) unsigned DEFAULT '0',
     PRIMARY KEY (`id`),
     UNIQUE KEY `idx_admin_id` (`admin_id`) USING BTREE,
     KEY `idx_sub` (`domain`,`sub_prefix`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- ----------------------------
-- Table structure for zp_adv
-- ----------------------------
DROP TABLE IF EXISTS `zp_adv`;
CREATE TABLE `zp_adv` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sort` tinyint(3) unsigned DEFAULT '0' COMMENT '渠道类型，0:微信小程序，1:抖音小程序，2:app，3:百度小程序',
  `name` varchar(255) DEFAULT NULL COMMENT '广告位名称',
  `advid` varchar(255) DEFAULT NULL COMMENT '广告位ID',
  `status` tinyint(4) DEFAULT '1' COMMENT '1启用2禁用',
  `type` tinyint(4) DEFAULT '1' COMMENT '广告类型  1:banner,2:激励,3:插屏,4:视频,5:格子,6:封面,7:原生模板',
  `ctime` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='广告';


-- ----------------------------
-- Table structure for zp_adv_set
-- ----------------------------
DROP TABLE IF EXISTS `zp_adv_set`;
CREATE TABLE `zp_adv_set` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sort` tinyint(3) unsigned DEFAULT '0' COMMENT '渠道类型，0:微信小程序，1:抖音小程序，2:app，3:百度小程序',
  `aid` int(11) DEFAULT NULL COMMENT 'advID',
  `type` tinyint(4) DEFAULT NULL COMMENT '广告类型',
  `adsense` tinyint(4) DEFAULT '1' COMMENT '1:首页,2:资源页,3:收藏页,4:个人中心,5:我的资源,6:我的人脉',
  `ctime` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='广告位置';

-- ----------------------------
-- Table structure for zp_article
-- ----------------------------
DROP TABLE IF EXISTS `zp_article`;
CREATE TABLE `zp_article` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `sort_id` int(10) unsigned DEFAULT '0' COMMENT '资讯类型',
  `title` varchar(100) DEFAULT NULL COMMENT '标题中文',
  `thumb` varchar(150) DEFAULT NULL,
  `content` text COMMENT '内容',
  `is_out` tinyint(3) unsigned DEFAULT '0' COMMENT '是否站外，1站外，0站内',
  `is_top` tinyint(1) unsigned DEFAULT '0' COMMENT '是否置顶，1置顶，0不置顶',
  `links` varchar(480) DEFAULT NULL COMMENT '站外链接',
  `views` int(255) unsigned DEFAULT '0' COMMENT '浏览次数',
  `admin_id` int(10) unsigned DEFAULT '0' COMMENT '发布人ID',
  `status` tinyint(3) unsigned DEFAULT '0' COMMENT '状态，1启用，0禁用',
  `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文章列表';

