INSERT INTO `zp_article` VALUES ('11', '7', 'SVIP介绍', '', '<h1>1.在开始学习之前，花点时间了解几个基本的概念，可以帮助您更快熟悉智创云享。</h1><p>在智创云享中，您可以报名任意的课程，每个课程中含有若干节，每个节下会有若干个学习任务，学习任务的类型包括：直播任务、录播任务、习题任务等，您可以通过各种类型的任务进行学习。</p><p>当您完成所有的学习任务后，就完成了该门课程的学习。</p><p>各种课程、章节、学习任务由授课老师安排，如果在课程内容上有任何建议，您可以联系老师沟通。</p><p>2.在智创云享可以做什么？</p><p>学习！学习！学习！</p><p>好学的您可以通过在线直播来与老师实时互动，通过录播视频随时随地学习，通过习题任务进一步地巩固所学的知识，同时可以下载相关学习资料。</p><p>当然，效率也很重要！</p><p>课程表帮您更好地管理自己的学习。</p><p>PC网页：您可以在“个人中心 -&gt; 课程表”页面中查看报名课程以及即将开始的课程。</p><p>移动端APP：您可以在“课程表”页面中查看报名课程以及即将开始的课程。</p><p>&nbsp;</p><p>&nbsp;</p><p>3.如何开始学习？</p><p>首先，您需要登录智创云享，报名该课程。</p><p>免费课点击课程详情页中的免费报名，即可报名该课程。</p><p><br/></p>', '0', '1', '', '542', '1', '1', '1692605746');INSERT INTO `zp_article` VALUES ('13', '4', '会员服务协议', '', '<p>付费会员协议</p><p>请认真阅读并理解以下内容，本协议是您与西安众邦网络科技有限公司之间就SVIP会员所订立的契约。请您仔细阅读本协议，会员购买成功后本协议即构成对双方有约束力的法律文件。</p><p>第1条 相关定义</p><p>1.1 SVIP会员:SVIP 会员是为商城客户打造的高级会员服务，通过提供高品质的客户服务，让网购变的更加方便，省钱和放心。</p><p>1.5 实名信息:用户开通SVIP会员需保证商城用户信息真实，同一自然人如有多个商城账号，可同时开通对应的多个会员。</p><p>第2条 本站服务条款的确认和接纳</p><p>2.1本站所提供的SVIP会员试用期及正式期活动的所有权和运作权归本公司所有。</p><p>2.2 用户支付会员成功，即视为用户确认自己同意接受SVIP会员相关服务的条款，且同意按本协议内容履行，如产生用户相关责任的，同意承担相应法律责任。</p><p>2.3 如果您在18周岁以下，您只能在父母或监护人的监护参与下方能参与体验该服务。</p><p>2.4 本公司保留在中华人民共和国大陆地区法施行之法律允许的范围内独自决定拒绝服务、关闭用户账户、清除或编辑</p><p>内容等相关权利。</p><p>2.5 SVIP会员开通后，您在已开通的服务期内不能主动取消服务或终止资格，</p><p><br/></p>', '0', '1', '', '5', '1', '1', '1708415195');
INSERT INTO `zp_article` VALUES ('13', '4', '会员服务协议', '', '<p>付费会员协议</p><p>请认真阅读并理解以下内容，本协议是您与智创云享之间就SVIP会员所订立的契约。请您仔细阅读本协议，会员购买成功后本协议即构成对双方有约束力的法律文件。</p><p>第1条 相关定义</p><p>1.1 SVIP会员:SVIP 会员是为商城客户打造的高级会员服务，通过提供高品质的客户服务，让网购变的更加方便，省钱和放心。</p><p>1.5 实名信息:用户开通SVIP会员需保证用户信息真实，同一自然人如有多个商城账号，可同时开通对应的多个会员。</p><p>第2条 本站服务条款的确认和接纳</p><p>2.1本站所提供的SVIP会员试用期及正式期活动的所有权和运作权归我们所有。</p><p>2.2 用户支付会员成功，即视为用户确认自己同意接受SVIP会员相关服务的条款，且同意按本协议内容履行，如产生用户相关责任的，同意承担相应法律责任。</p><p>2.3 如果您在18周岁以下，您只能在父母或监护人的监护参与下方能参与体验该服务。</p><p>2.4 本公司保留在中华人民共和国大陆地区法施行之法律允许的范围内独自决定拒绝服务、关闭用户账户、清除或编辑</p><p>内容等相关权利。</p><p>2.5 SVIP会员开通后，您在已开通的服务期内不能主动取消服务或终止资格，</p><p><br/></p>', '0', '1', '', '5', '1', '1', '1708415195');


-- ----------------------------
-- Table structure for zp_article_sort
-- ----------------------------
DROP TABLE IF EXISTS `zp_article_sort`;
CREATE TABLE `zp_article_sort` (
   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
   `pid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '父ID',
   `name` varchar(30) DEFAULT NULL COMMENT '类型名称',
   `indexid` int(10) unsigned DEFAULT '0' COMMENT '排序',
   `status` tinyint(3) unsigned DEFAULT '0' COMMENT '状态，1启用，0禁用',
   `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
   PRIMARY KEY (`id`),
   KEY `idx_pid` (`pid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文章分类';

