-- ----------------------------
-- Table structure for zp_attachment
-- ----------------------------
DROP TABLE IF EXISTS `zp_attachment`;
CREATE TABLE `zp_attachment` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
 `pid` int(10) unsigned DEFAULT '0' COMMENT '所属分类',
 `name` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名称',
 `real_name` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '真实名称',
 `att_dir` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '原路径',
 `satt_dir` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '现路径',
 `att_size` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '大小',
 `att_type` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '类型',
 `up_type` tinyint(1) unsigned DEFAULT '0' COMMENT '上传类型：1本地，2阿里云，3腾讯云，4七牛云',
 `mode_type` tinyint(1) unsigned DEFAULT '0' COMMENT '上传来源：1后端，2前端',
 `ctime` int(10) unsigned DEFAULT NULL COMMENT '时间',
 PRIMARY KEY (`id`),
 KEY `idx_pid` (`pid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='素材列表';

