-- ----------------------------
-- Table structure for zp_attachment_sort
-- ----------------------------
DROP TABLE IF EXISTS `zp_attachment_sort`;
CREATE TABLE `zp_attachment_sort` (
`id` int(10) unsigned NOT NULL AUTO_INCREMENT,
`pid` int(10) unsigned DEFAULT '0' COMMENT '父ID',
`name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名称',
`ctime` int(11) unsigned DEFAULT '0',
PRIMARY KEY (`id`),
KEY `idx_pid` (`pid`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='素材分类';

-- ----------------------------
-- Records of zp_attachment_sort
-- ----------------------------
INSERT INTO `zp_attachment_sort` VALUES ('1', '0', '系统自带', '0');
INSERT INTO `zp_attachment_sort` VALUES ('2', '0', '分类图标', '0');
