-- ----------------------------
-- Table structure for zp_audio_course
-- ----------------------------
DROP TABLE IF EXISTS `zp_audio_course`;
CREATE TABLE `zp_audio_course` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`title` varchar(150) DEFAULT NULL COMMENT '课程标题',
`thumb` varchar(128) DEFAULT NULL COMMENT '封面图',
`url` varchar(255) DEFAULT NULL COMMENT '课程地址',
`desc` varchar(255) DEFAULT NULL COMMENT '简介',
`rid` int(11) DEFAULT NULL COMMENT '资源ID',
`times` varchar(24) DEFAULT NULL COMMENT '时长',
`is_try` tinyint(1) DEFAULT '0' COMMENT '是否试看',
`indexid` int(11) DEFAULT NULL COMMENT '排序',
`ctime` int(11) DEFAULT NULL,
PRIMARY KEY (`id`),
KEY `idx_rid` (`rid`),
KEY `union_where` (`rid`,`indexid`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='音频课程';

-- ----------------------------
-- Table structure for zp_auth_group
-- ----------------------------
DROP TABLE IF EXISTS `zp_auth_group`;
CREATE TABLE `zp_auth_group` (
 `id` int(8) unsigned NOT NULL AUTO_INCREMENT,
 `title` char(50) NOT NULL DEFAULT '' COMMENT '标题',
 `status` tinyint(1) unsigned DEFAULT '0' COMMENT '状态',
 `rules` longtext COMMENT '规则',
 `is_auth` tinyint(1) unsigned DEFAULT '1' COMMENT '是否区分数据，0：不区分，1：区分',
 `ctime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
 PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='管理权限组';

-- ----------------------------
-- Records of zp_auth_group
-- ----------------------------
