-- ----------------------------
-- Table structure for zp_auth_rule
-- ----------------------------
DROP TABLE IF EXISTS `zp_auth_rule`;
CREATE TABLE `zp_auth_rule` (
`id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT,
`pid` int(5) NOT NULL DEFAULT '0' COMMENT '父栏目ID',
`method` varchar(12) DEFAULT NULL COMMENT '接口请求方式',
`href` char(80) NOT NULL DEFAULT '',
`title` char(20) NOT NULL DEFAULT '',
`type` tinyint(1) NOT NULL DEFAULT '1',
`open` tinyint(2) NOT NULL DEFAULT '1' COMMENT '是否开启验证',
`icon` varchar(20) DEFAULT NULL COMMENT '样式',
`condition` char(100) DEFAULT '',
`sort` int(11) DEFAULT '0' COMMENT '排序',
`status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '权限状态，1开启，0关闭',
`ctime` int(11) NOT NULL DEFAULT '0' COMMENT '添加时间',
`is_menu` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '1显示菜单，0不显示',
PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='权限表';

