-- ----------------------------
-- Table structure for zp_bill
-- ----------------------------
DROP TABLE IF EXISTS `zp_bill`;
CREATE TABLE `zp_bill` (
`id` int(10) unsigned NOT NULL AUTO_INCREMENT,
`admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
`pid` int(11) DEFAULT '0' COMMENT '推广人id',
`type` tinyint(3) unsigned DEFAULT '0' COMMENT '类型，1资源收益，2会员收益，3提现',
`mode` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '模式，1：增加，2：减少',
`before` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '操作前余额',
`money` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '金额',
`after` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '操作后余额',
`remark` varchar(200) DEFAULT NULL COMMENT '备注',
`order_id` int(10) unsigned DEFAULT '0' COMMENT '业务ID',
`uid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
`ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
PRIMARY KEY (`id`),
KEY `idx_user` (`admin_id`,`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='余额操作日志';

-- ----------------------------
-- Table structure for zp_cash
-- ----------------------------
DROP TABLE IF EXISTS `zp_cash`;
CREATE TABLE `zp_cash` (
`id` int(11) unsigned NOT NULL AUTO_INCREMENT,
`type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '方式:1=支付宝,2=微信,3=其他',
`pid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '上级代理ID',
`money` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '提现余额',
`fee` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '手续费',
`amount` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '实际付款金额',
`image` varchar(128) DEFAULT NULL COMMENT '收款码',
`remark` varchar(256) DEFAULT NULL COMMENT '备注',
`bank` varchar(64) DEFAULT NULL COMMENT '开户行',
`truename` varchar(32) DEFAULT NULL COMMENT '开户名',
`bankno` varchar(32) DEFAULT NULL COMMENT '银行卡号',
`reason` varchar(256) DEFAULT NULL COMMENT '审核操作原因',
`status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '审核状态:0=审核中,1=通过,-1=不通过,2=已打款(完成)',
`uid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '申请提现用户',
`utime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
`ctime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '申请时间',
PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='代理提现明细';

-- ----------------------------
-- Records of zp_cash
-- ----------------------------

-- ----------------------------
-- Table structure for zp_config
-- ----------------------------
DROP TABLE IF EXISTS `zp_config`;
CREATE TABLE `zp_config` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属分组',
 `types` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
 `title` varchar(35) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置标题',
 `name` varchar(35) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置项名称',
 `values` varchar(280) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置值',
 `default` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '默认值',
 `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注说明',
 `indexid` int(10) unsigned DEFAULT '0' COMMENT '排序',
 `status` tinyint(1) unsigned DEFAULT NULL COMMENT '状态，1启用，0禁用',
 `ctime` int(10) unsigned DEFAULT NULL COMMENT '0',
 PRIMARY KEY (`id`),
 KEY `idx_group` (`group`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='参数配置表';

