-- ----------------------------
-- Table structure for zp_groups
-- ----------------------------
DROP TABLE IF EXISTS `zp_groups`;
CREATE TABLE `zp_groups` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `name` varchar(32) DEFAULT NULL COMMENT '社群名称',
 `desc` varchar(256) DEFAULT NULL COMMENT '简介',
 `thumb` varchar(128) DEFAULT NULL COMMENT '社群图片',
 `url` varchar(128) DEFAULT NULL COMMENT '社区二维码',
 `status` tinyint(2) unsigned DEFAULT '0' COMMENT '状态，1上线，0下线',
 `uid` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
 `exp_time` int(10) unsigned DEFAULT '0' COMMENT '过期时间',
 `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
 PRIMARY KEY (`id`),
 KEY `idx_union` (`uid`,`exp_time`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='社群';

-- ----------------------------
-- Table structure for zp_invite
-- ----------------------------
DROP TABLE IF EXISTS `zp_invite`;
CREATE TABLE `zp_invite` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
 `rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID，大于0为通过资源邀请助力',
 `pid` int(10) unsigned DEFAULT '0' COMMENT '邀请人ID',
 `uid` int(10) unsigned DEFAULT '0' COMMENT '被邀请人ID',
 `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
 PRIMARY KEY (`id`),
 KEY `idx_union` (`pid`,`uid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邀请用户助力表';

-- ----------------------------
-- Table structure for zp_jump
-- ----------------------------
DROP TABLE IF EXISTS `zp_jump`;
CREATE TABLE `zp_jump` (
`id` int(10) unsigned NOT NULL AUTO_INCREMENT,
`name` varchar(32) NOT NULL COMMENT '跳转名称',
`desc` varchar(256) DEFAULT NULL COMMENT '简介',
`appid` varchar(50) DEFAULT NULL,
`url` varchar(128) DEFAULT NULL COMMENT '链接地址',
`type` tinyint(4) unsigned DEFAULT '1' COMMENT '1外部链接2小程序',
`thumb` varchar(128) DEFAULT NULL COMMENT '封面图标',
`status` tinyint(2) unsigned DEFAULT '0' COMMENT '状态，1启用，0禁用',
`uid` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
`ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
PRIMARY KEY (`id`),
KEY `idx_union` (`uid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='社群';

-- ----------------------------
-- Table structure for zp_kammi
-- ----------------------------
DROP TABLE IF EXISTS `zp_kammi`;
CREATE TABLE `zp_kammi` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
`type` tinyint(1) unsigned DEFAULT '1' COMMENT '卡密类型：1资源，2会员',
`cdkey` varchar(100) DEFAULT NULL,
`money` decimal(11,2) DEFAULT NULL COMMENT '价格',
`rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID',
`vid` int(10) unsigned DEFAULT '0' COMMENT '会员ID',
`uid` int(11) unsigned DEFAULT '0' COMMENT '使用用户',
`status` tinyint(2) DEFAULT '0' COMMENT '0未使用1已使用',
`utime` int(10) unsigned DEFAULT '0' COMMENT '使用时间',
`ctime` int(11) DEFAULT NULL,
PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='卡密表';

-- ----------------------------
-- Table structure for zp_links
-- ----------------------------
DROP TABLE IF EXISTS `zp_links`;
CREATE TABLE `zp_links` (
`id` int(10) unsigned NOT NULL AUTO_INCREMENT,
`type` tinyint(1) unsigned DEFAULT '0' COMMENT '类型，0首页',
`name` varchar(48) DEFAULT NULL COMMENT '链接名称',
`url` varchar(128) DEFAULT NULL COMMENT '链接',
`remark` varchar(256) DEFAULT NULL COMMENT '备注',
`indexid` int(10) unsigned DEFAULT '0' COMMENT '排序',
`status` tinyint(1) unsigned DEFAULT '1' COMMENT '状态，1启用，0禁用',
`ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
PRIMARY KEY (`id`),
KEY `idx_indexid` (`indexid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='友情链接表';

