-- ----------------------------
-- Table structure for zp_market_log
-- ----------------------------
DROP TABLE IF EXISTS `zp_market_log`;
CREATE TABLE `zp_market_log` (
 `id` int(11) NOT NULL AUTO_INCREMENT,
 `title` varchar(150) DEFAULT NULL COMMENT '标题',
 `content` varchar(450) DEFAULT NULL COMMENT '内容',
 `ctime` int(11) DEFAULT NULL,
 PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='资源市场记录';

-- ----------------------------
-- Table structure for zp_order
-- ----------------------------
DROP TABLE IF EXISTS `zp_order`;
CREATE TABLE `zp_order` (
    `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
    `ordno` char(48) DEFAULT NULL COMMENT '订单号',
    `admin_id` int(11) unsigned DEFAULT '0' COMMENT '代理id',
    `pid` int(11) unsigned DEFAULT '0' COMMENT '会员邀请人ID',
    `uid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
    `is_kl` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否扣量:1=扣量,0=不扣量',
    `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
    `type` tinyint(1) unsigned DEFAULT '1' COMMENT '付费类型:1购买资源2购买会员',
    `vid` int(11) DEFAULT '0' COMMENT 'svipID',
    `rid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '资源ID',
    `pay_type` int(11) unsigned DEFAULT '0' COMMENT '支付类型：1微信2支付宝3卡密4抖音',
    `platform` varchar(24) DEFAULT NULL COMMENT '支付平台:,wechat_mini:微信小程序,wechat_official:微信公众号，wechat_h5:微信H5，wechat_native:微信扫码，alipay_h5:支付宝H5，alipay_pc:支付宝网页，douyin:抖音支付',
    `money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '支付金额',
    `pt_money` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '实际收入',
    `hr_money` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '会员抽成',
    `sr_money` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '二级分佣金额',
    `tc_money` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '上级代理提成',
    `tp_money` decimal(12,2) unsigned DEFAULT '0.00' COMMENT '上上级代理抽成',
    `ps_money` decimal(12,2) unsigned DEFAULT '0.00' COMMENT '分账金额',
    `is_profit` tinyint(2) unsigned DEFAULT '0' COMMENT '是否分账',
    `trade_id` varchar(64) DEFAULT NULL COMMENT '第三方订单号',
    `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '支付状态:1=已支付,0=未支付,2已取消',
    `refund_status` tinyint(2) DEFAULT '0' COMMENT '退款状态，0正常，1退款中，2退款成功，-1退款失败',
    `remark` varchar(128) DEFAULT NULL COMMENT '备注',
    `ptime` int(11) unsigned DEFAULT '0' COMMENT '支付时间',
    `utime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '修改时间',
    `ctime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '下单时间',
    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE KEY `order` (`ordno`) USING BTREE,
    KEY `uid` (`uid`) USING BTREE,
    KEY `uids` (`status`,`uid`) USING BTREE,
    KEY `uc` (`uid`,`status`,`ctime`) USING BTREE,
    KEY `idx_uid_kl` (`uid`,`is_kl`,`money`),
    KEY `idx_uid_status` (`uid`,`money`,`status`),
    KEY `idx_status` (`status`),
    KEY `idx_uid_ctime` (`uid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单记录';

-- ----------------------------
-- Table structure for zp_pages
-- ----------------------------
DROP TABLE IF EXISTS `zp_pages`;
CREATE TABLE `zp_pages` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`type` tinyint(1) unsigned DEFAULT '0' COMMENT '类型，0目录，1普通，2列表，3链接',
`pid` int(10) unsigned DEFAULT '0' COMMENT '父级ID',
`name` varchar(48) DEFAULT NULL COMMENT '页面名称',
`path` varchar(128) DEFAULT NULL COMMENT '页面路径',
`is_tab` tinyint(1) unsigned DEFAULT '0' COMMENT 'tab导航页，1导航页,普通页',
`remark` varchar(128) DEFAULT NULL COMMENT '备注说明',
`ctime` int(11) unsigned DEFAULT '0' COMMENT '添加时间',
PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='前端页面表';

