-- ----------------------------
-- Table structure for zp_poster_config
-- ----------------------------
DROP TABLE IF EXISTS `zp_poster_config`;
CREATE TABLE `zp_poster_config` (
`id` int(10) unsigned NOT NULL AUTO_INCREMENT,
`type` tinyint(2) unsigned NOT NULL DEFAULT '1' COMMENT '海报类型，1为资源海报，2推广海报',
`admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理用户ID',
`setting` text COMMENT '配置信息',
`utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
`ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='资源分享海报自定义';

-- ----------------------------
-- Table structure for zp_privilege
-- ----------------------------
DROP TABLE IF EXISTS `zp_privilege`;
CREATE TABLE `zp_privilege` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`name` varchar(48) DEFAULT NULL COMMENT '特权名称',
`type` int(5) unsigned DEFAULT '1' COMMENT '1资源级别2资源数量3资源分类4广告5佣金',
`rule` text COMMENT '权限配置',
`url` varchar(128) DEFAULT NULL COMMENT '权益图标',
`desc` varchar(256) DEFAULT NULL COMMENT '权益简介',
`status` tinyint(1) unsigned DEFAULT '0' COMMENT '状态，1启用，0禁用',
`ctime` int(11) DEFAULT NULL,
PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='特权表';

