-- ----------------------------
-- Table structure for zp_refund_log
-- ----------------------------
DROP TABLE IF EXISTS `zp_refund_log`;
CREATE TABLE `zp_refund_log` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `type` tinyint(1) unsigned DEFAULT '0' COMMENT '1微信支付，2支付宝',
 `ordno` char(48) DEFAULT NULL COMMENT '订单号',
 `refund_ordno` char(48) DEFAULT NULL COMMENT '退款单号',
 `money` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '订单金额',
 `refund_money` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '退款金额',
 `trade_id` varchar(64) DEFAULT NULL COMMENT '第三方交易流水号',
 `status` tinyint(2) DEFAULT '0' COMMENT '0待处理，1提交成功，2退款成功，-1提交失败，-2退款失败',
 `remark` varchar(64) DEFAULT NULL COMMENT '退款备注',
 `reason` varchar(64) DEFAULT NULL COMMENT '退款失败原因',
 `utime` int(10) unsigned DEFAULT '0' COMMENT '退款成功时间',
 `ctime` int(10) unsigned DEFAULT '0' COMMENT '退款提交时间',
 PRIMARY KEY (`id`),
 KEY `idx_ordno` (`ordno`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单退款记录表';

-- ----------------------------
-- Table structure for zp_resource
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource`;
CREATE TABLE `zp_resource` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`type` tinyint(4) DEFAULT '1' COMMENT '资源类型：1网盘，2视频，3文章',
`admin_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '代理ID',
`title` varchar(255) NOT NULL COMMENT '标题',
`thumb` varchar(255) NOT NULL COMMENT '封面图',
`views` int(11) DEFAULT '0' COMMENT '阅读次数',
`favs` int(11) DEFAULT '0' COMMENT '收藏',
`link` varchar(256) DEFAULT NULL COMMENT '资源地址',
`ext_code` varchar(15) DEFAULT NULL COMMENT '提取码',
`status` tinyint(4) DEFAULT '1' COMMENT '状态，0禁用，1上架',
`price` decimal(10,2) DEFAULT '0.00' COMMENT '价格',
`dis_price` decimal(10,2) DEFAULT '0.00' COMMENT '划线价格',
`is_top` tinyint(4) DEFAULT '0' COMMENT '置顶:0否1是',
`desc` varchar(255) DEFAULT NULL COMMENT '简介',
`is_show` tinyint(255) DEFAULT '0' COMMENT '内容显示：0否1是',
`is_fenxiao` tinyint(4) DEFAULT '0' COMMENT '参与分销：0否1是',
`sell_set` tinyint(4) DEFAULT '1' COMMENT '佣金设置：1合伙人设置2商品设置',
`sell_type` tinyint(4) DEFAULT '1' COMMENT '佣金分配方式：1百分比2固定金额',
`sell` varchar(10) DEFAULT NULL COMMENT '佣金',
`sell_type2` tinyint(2) unsigned DEFAULT '0' COMMENT '二级分销设置方式',
`sell2` varchar(10) DEFAULT NULL COMMENT '二级佣金设置',
`sales` int(11) DEFAULT '0' COMMENT '销量',
`edition` int(10) unsigned DEFAULT '0' COMMENT '定制功能的版本',
`level` int(11) DEFAULT '1' COMMENT '1低级2中级3高级',
`invite` tinyint(4) DEFAULT '0' COMMENT '邀请任务：0关闭1开启',
`invite_num` int(11) DEFAULT '0' COMMENT '邀请人数',
`is_buy` tinyint(4) DEFAULT '0' COMMENT '购买，0否1是',
`is_sell` tinyint(4) DEFAULT '0' COMMENT '出售，0否1是-1未通过',
`pages` int(10) unsigned DEFAULT '0' COMMENT '文档页数',
`exc_video` tinyint(4) DEFAULT '0' COMMENT '激励视频：0关闭1开启',
`sync_id` int(10) unsigned DEFAULT '0' COMMENT '同步资源ID',
`uid` int(11) DEFAULT '0',
`utime` int(11) DEFAULT '0',
`ctime` int(11) DEFAULT '0',
PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='资源表';

-- ----------------------------
-- Table structure for zp_resource_info
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_info`;
CREATE TABLE `zp_resource_info` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`rid` int(10) unsigned DEFAULT '0' COMMENT '资源关联ID',
`free_content` text CHARACTER SET utf8 COMMENT '免费资源介绍',
`content` text CHARACTER SET utf8 COMMENT '资源介绍',
PRIMARY KEY (`id`),
KEY `idx_rid` (`rid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='资源介绍内容表';



-- ----------------------------
-- Table structure for zp_resource_kammi
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_kammi`;
CREATE TABLE `zp_resource_kammi` (
 `id` int(11) NOT NULL AUTO_INCREMENT,
 `cdkey` varchar(128) DEFAULT NULL COMMENT '卡密',
 `rid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '资源ID',
 `uid` int(11) unsigned DEFAULT '0' COMMENT '用户ID',
 `status` tinyint(2) unsigned DEFAULT '0' COMMENT '0未使用1已使用',
 `utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
 `ctime` int(11) DEFAULT '0',
 PRIMARY KEY (`id`),
 KEY `idx_where` (`rid`,`uid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='卡密资源';


-- ----------------------------
-- Table structure for zp_resource_level
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_level`;
CREATE TABLE `zp_resource_level` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `name` varchar(48) DEFAULT NULL COMMENT '等级名称',
 `indexid` int(11) unsigned DEFAULT '0' COMMENT '排序',
 `status` tinyint(2) unsigned DEFAULT '1' COMMENT '状态',
 `ctime` int(11) unsigned DEFAULT '0',
 PRIMARY KEY (`id`),
 KEY `idx_index` (`indexid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='资源等级';

