-- ----------------------------
-- Table structure for zp_resource_sort
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_sort`;
CREATE TABLE `zp_resource_sort` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `pid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '父ID',
    `name` varchar(48) NOT NULL COMMENT '分类名称',
    `thumb` varchar(128) DEFAULT NULL COMMENT '封面图',
    `status` tinyint(4) DEFAULT '1' COMMENT '是否启用：0禁用1启用',
    `indexid` tinyint(4) DEFAULT '0' COMMENT '排序',
    `ctime` int(11) DEFAULT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_pid` (`pid`),
    KEY `idx_sort` (`indexid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='资源类型表';

