-- ----------------------------
-- Table structure for zp_resource_task
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_task`;
CREATE TABLE `zp_resource_task` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `rid` int(11) NOT NULL COMMENT '资源ID',
    `admin_id` int(11) NOT NULL COMMENT '代理ID',
    `uid` int(11) NOT NULL,
    `invite_num` int(11) DEFAULT '0' COMMENT '邀请人数',
    `is_video` int(11) DEFAULT '0' COMMENT '视频任务',
    `status` tinyint(2) unsigned DEFAULT '0' COMMENT '任务完成情况，0未完成，1已完成',
    `utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
    `ctime` int(11) unsigned DEFAULT '0' COMMENT '创建时间',
    PRIMARY KEY (`id`),
    KEY `idx_task` (`uid`,`rid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邀请任务表';

-- ----------------------------
-- Table structure for zp_resource_type
-- ----------------------------
DROP TABLE IF EXISTS `zp_resource_type`;
CREATE TABLE `zp_resource_type` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `rid` int(11) NOT NULL COMMENT '资源ID',
    `sid` int(11) NOT NULL COMMENT '资源类型ID',
    `ctime` int(11) DEFAULT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_sid` (`sid`),
    KEY `idx_rid` (`rid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='资源分类关联表';

-- ----------------------------
-- Table structure for zp_setting
-- ----------------------------
DROP TABLE IF EXISTS `zp_setting`;
CREATE TABLE `zp_setting` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `skey` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '键值',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '数据',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_keys` (`skey`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='配置数据表';

