-- ----------------------------
-- Table structure for zp_shopping_cart
-- ----------------------------
DROP TABLE IF EXISTS `zp_shopping_cart`;
CREATE TABLE `zp_shopping_cart` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`thumb` varchar(255) DEFAULT NULL COMMENT '封面图',
`title` varchar(255) DEFAULT NULL COMMENT '标题',
`money` decimal(10,2) DEFAULT NULL COMMENT '价格',
`rid` int(11) DEFAULT NULL COMMENT '资源ID',
`ctime` int(11) DEFAULT NULL,
PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='购物车';

-- ----------------------------
-- Records of zp_shopping_cart
-- ----------------------------

-- ----------------------------
-- Table structure for zp_site_order
-- ----------------------------
DROP TABLE IF EXISTS `zp_site_order`;
CREATE TABLE `zp_site_order` (
 `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
 `admin_id` int(10) unsigned DEFAULT '0' COMMENT '上级代理ID',
 `ordno` varchar(24) DEFAULT NULL COMMENT '订单号',
 `money` decimal(12,2) unsigned DEFAULT '0.00' COMMENT '金额',
 `svip_id` int(10) unsigned DEFAULT '0' COMMENT 'svipID',
 `prefix` varchar(64) DEFAULT NULL COMMENT '前缀名称',
 `username` varchar(48) DEFAULT NULL COMMENT '用户名',
 `password` varchar(48) DEFAULT NULL COMMENT '密码',
 `suffix` varchar(48) DEFAULT NULL COMMENT '域名后缀',
 `mobile` varchar(24) DEFAULT NULL COMMENT '手机号码',
 `webname` varchar(64) DEFAULT NULL COMMENT '分站名称',
 `uid` int(10) unsigned DEFAULT '0' COMMENT '用户ID',
 `status` tinyint(2) unsigned DEFAULT '0' COMMENT '0未支付，1已支付',
 `utime` int(11) DEFAULT '0' COMMENT '更新时间',
 `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
 PRIMARY KEY (`id`),
 KEY `idx_ordno` (`ordno`) USING BTREE,
 KEY `idx_svip_id` (`svip_id`),
 KEY `idx_site` (`uid`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='自助分站订单';

-- ----------------------------
-- Table structure for zp_spread
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread`;
CREATE TABLE `zp_spread` (
 `id` int(11) NOT NULL AUTO_INCREMENT,
 `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
 `type` tinyint(4) DEFAULT '1' COMMENT '资源类型：1网盘，2视频，3文章',
 `title` varchar(64) NOT NULL COMMENT '标题',
 `thumb` varchar(128) NOT NULL COMMENT '封面图',
 `views` int(11) unsigned DEFAULT '0' COMMENT '阅读次数',
 `favs` int(11) unsigned DEFAULT '0' COMMENT '收藏',
 `link` varchar(256) DEFAULT NULL COMMENT '资源地址',
 `ext_code` varchar(15) DEFAULT NULL COMMENT '提取码',
 `status` tinyint(2) unsigned DEFAULT '1' COMMENT '状态，0禁用，1上架',
 `price` decimal(10,2) DEFAULT '0.00' COMMENT '价格',
 `dis_price` decimal(10,2) DEFAULT '0.00' COMMENT '划线价格',
 `is_top` tinyint(4) DEFAULT '0' COMMENT '置顶:0否1是',
 `edition` int(10) unsigned DEFAULT '0' COMMENT '定制功能的版本',
 `desc` varchar(256) DEFAULT NULL COMMENT '简介',
 `is_vip` tinyint(4) DEFAULT '-1' COMMENT '是否VIP专属，指定会员，0所有会员，-1普通',
 `is_fenxiao` tinyint(1) DEFAULT '0' COMMENT '参与分销：0否1是',
 `sell_set` tinyint(4) DEFAULT '1' COMMENT '佣金设置：1合伙人设置2商品设置',
 `sell_type` tinyint(2) DEFAULT '1' COMMENT '佣金分配方式：1百分比2固定金额',
 `sell` varchar(10) DEFAULT NULL COMMENT '佣金',
 `sell_type2` tinyint(2) unsigned DEFAULT '0' COMMENT '二级分销设置方式',
 `sell2` varchar(10) DEFAULT NULL COMMENT '二级佣金设置',
 `sales` int(11) unsigned DEFAULT '0' COMMENT '销量',
 `level` tinyint(1) unsigned DEFAULT '1' COMMENT '1低级2中级3高级',
 `invite` tinyint(1) unsigned DEFAULT '0' COMMENT '邀请任务：0关闭1开启',
 `invite_num` int(11) unsigned DEFAULT '0' COMMENT '邀请人数',
 `exc_video` tinyint(1) unsigned DEFAULT '0' COMMENT '激励视频：0关闭，1开启',
 `try_see` int(10) unsigned DEFAULT '0' COMMENT '视频试看时间',
 `pages` int(10) unsigned DEFAULT '0' COMMENT '文档页数',
 `rid` int(11) unsigned DEFAULT '0' COMMENT '资源ID',
 `uid` int(11) unsigned DEFAULT '0' COMMENT '代理用户ID',
 `utime` int(11) unsigned DEFAULT '0' COMMENT '更新时间',
 `ctime` int(11) unsigned DEFAULT '0' COMMENT '创建时间',
 PRIMARY KEY (`id`),
 KEY `idx_type` (`status`,`type`),
 KEY `uid` (`uid`),
 KEY `idx_where` (`id`,`status`),
 KEY `idx_adminid` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='资源推广表';

-- ----------------------------
-- Table structure for zp_spread_group
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread_group`;
CREATE TABLE `zp_spread_group` (
   `id` int(11) NOT NULL AUTO_INCREMENT,
   `rid` int(10) unsigned DEFAULT '0' COMMENT '推广资源ID',
   `gid` int(10) unsigned DEFAULT '0' COMMENT '社区ID',
   `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
   PRIMARY KEY (`id`),
   KEY `idx_union` (`rid`,`gid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='推广资源关联社群';


-- ----------------------------
-- Table structure for zp_spread_hand
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread_hand`;
CREATE TABLE `zp_spread_hand` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `admin_id` int(10) unsigned DEFAULT '0',
  `rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID',
  `r_uid` int(10) unsigned DEFAULT '0' COMMENT '被助力用户',
  `uid` int(10) unsigned DEFAULT '0' COMMENT '助力用户',
  `ctime` int(10) unsigned DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_where` (`r_uid`,`uid`,`rid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='用户助力表';


-- ----------------------------
-- Table structure for zp_spread_jump
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread_jump`;
CREATE TABLE `zp_spread_jump` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rid` int(10) unsigned DEFAULT '0' COMMENT '推广资源ID',
  `jid` int(10) unsigned DEFAULT '0' COMMENT '跳转ID',
  `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
  PRIMARY KEY (`id`),
  KEY `idx_union` (`rid`,`jid`,`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='推广资源关联跳转';


-- ----------------------------
-- Table structure for zp_spread_type
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread_type`;
CREATE TABLE `zp_spread_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rid` int(11) NOT NULL COMMENT '资源ID',
  `sid` int(11) NOT NULL COMMENT '资源类型ID',
  `ctime` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sid` (`sid`),
  KEY `idx_rid` (`rid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='推广资源分类关联表';


-- ----------------------------
-- Table structure for zp_spread_view
-- ----------------------------
DROP TABLE IF EXISTS `zp_spread_view`;
CREATE TABLE `zp_spread_view` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
  `r_id` int(10) unsigned DEFAULT '0' COMMENT '视频ID',
  `num` int(10) unsigned DEFAULT '0' COMMENT '累计数量',
  `ip` varchar(48) DEFAULT NULL COMMENT 'ip地址',
  `uid` int(10) unsigned DEFAULT '0' COMMENT '所属用户ID',
  `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='访问记录';

-- ----------------------------
-- Table structure for zp_svip
-- ----------------------------
DROP TABLE IF EXISTS `zp_svip`;
CREATE TABLE `zp_svip` (
   `id` int(11) NOT NULL AUTO_INCREMENT,
   `admin_id` int(10) unsigned DEFAULT '1' COMMENT '所属代理ID',
   `type` tinyint(2) unsigned DEFAULT '0' COMMENT '0，默认会员VIP,1为代理套餐',
   `name` varchar(32) DEFAULT NULL COMMENT '套餐名称',
   `days` int(11) unsigned DEFAULT '0' COMMENT '套餐天数',
   `price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '价格',
   `invite_num` int(11) unsigned DEFAULT '0' COMMENT '邀请任务',
   `level` tinyint(4) unsigned DEFAULT '0' COMMENT '套餐级别',
   `discount` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '折扣',
   `content` varchar(256) DEFAULT NULL COMMENT '会员权益介绍',
   `open` tinyint(1) unsigned DEFAULT '1' COMMENT '前端显示状态，1显示，2隐藏',
   `status` tinyint(2) unsigned DEFAULT '0' COMMENT '状态：0，禁用，1启用',
   `ctime` int(11) unsigned DEFAULT '0' COMMENT '添加时间',
   PRIMARY KEY (`id`),
   KEY `idx_admin_id` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SVIP设置';

