-- ----------------------------
-- Table structure for zp_svip_log
-- ----------------------------
DROP TABLE IF EXISTS `zp_svip_log`;
CREATE TABLE `zp_svip_log` (
       `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
       `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
       `type` tinyint(2) unsigned DEFAULT '0' COMMENT '升级方式，1购买，2任务，3手动',
       `vid` int(10) unsigned DEFAULT '0' COMMENT '会员等级ID',
       `exp_time` int(10) unsigned DEFAULT '0' COMMENT '过期时间',
       `uid` int(10) unsigned DEFAULT '0' COMMENT '用户ID',
       `ctime` int(10) unsigned DEFAULT '0' COMMENT '升级时间',
       PRIMARY KEY (`id`),
       KEY `idx_admin_id` (`admin_id`),
       KEY `idx_uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员升级记录';

-- ----------------------------
-- Table structure for zp_svip_privilege
