     `vid` int(11) NOT NULL COMMENT '会员类型ID',
     `pid` int(11) NOT NULL COMMENT '特权ID',
     `ctime` int(11) DEFAULT NULL,
     PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员特权关联表';

