DROP TABLE IF EXISTS `zp_svip_task`;
CREATE TABLE `zp_svip_task` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `admin_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '代理ID',
    `uid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
