-- ----------------------------
-- Table structure for zp_swiper
-- ----------------------------
DROP TABLE IF EXISTS `zp_swiper`;
CREATE TABLE `zp_swiper` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
     `type` tinyint(1) unsigned DEFAULT '0' COMMENT '类型，0代理分站申请，1PC首页轮播',
     `title` varchar(50) DEFAULT NULL COMMENT '广告标题',
     `url` varchar(150) DEFAULT NULL COMMENT '广告图片',
     `link` varchar(50) DEFAULT NULL COMMENT '广告链接',
     `style` varchar(150) DEFAULT NULL COMMENT '背景颜色值',
     `status` tinyint(1) unsigned DEFAULT '1' COMMENT '状态，1启用，0禁用',
     `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
     PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='轮播广告图';

