-- ----------------------------
-- Table structure for zp_theme
-- ----------------------------
DROP TABLE IF EXISTS `zp_theme`;
CREATE TABLE `zp_theme` (
    `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
    `admin_id` int(10) unsigned DEFAULT '0' COMMENT '所属代理ID',
    `code` varchar(50) CHARACTER SET utf8 DEFAULT NULL COMMENT '可视化区域编码',
    `name` varchar(32) CHARACTER SET utf8 DEFAULT NULL COMMENT '可编辑区域名称',
    `style` varchar(200) DEFAULT NULL COMMENT '页面样式',
    `thumb` varchar(128) DEFAULT NULL COMMENT '模板封面',
    `desc` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT '描述',
    `type` tinyint(1) unsigned DEFAULT '1' COMMENT '1手机端，2PC端',
    `layout` tinyint(2) unsigned DEFAULT '1' COMMENT '布局样式1，首页，2专题页',
    `utime` int(10) unsigned DEFAULT '0' COMMENT '更新日期',
    `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='自定义布局表';

