-- ----------------------------
-- Table structure for zp_theme_config
-- ----------------------------
DROP TABLE IF EXISTS `zp_theme_config`;
CREATE TABLE `zp_theme_config` (
   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
   `admin_id` int(10) unsigned DEFAULT '0' COMMENT '所属代理ID',
   `name` varchar(32) DEFAULT NULL,
   `page` int(10) unsigned DEFAULT '0' COMMENT '页面名称,默认0，主题颜色，1个人中心，2分类',
   `params` text COMMENT '参数',
   `utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
   `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
   PRIMARY KEY (`id`),
   KEY `idx_admin_id` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='主题配置表';

