-- ----------------------------
-- Table structure for zp_theme_items
-- ----------------------------
DROP TABLE IF EXISTS `zp_theme_items`;
CREATE TABLE `zp_theme_items` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int(11) unsigned DEFAULT '0' COMMENT '代理ID',
  `widget_code` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '组件编码',
  `page_code` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '页面编码',
  `position_id` tinyint(2) unsigned NOT NULL DEFAULT '1' COMMENT '布局位置',
  `sort` tinyint(2) unsigned NOT NULL DEFAULT '1' COMMENT '排序，越小越靠前',
  `params` text CHARACTER SET utf8 COMMENT '组件配置内容',
  `ctime` int(10) unsigned DEFAULT '0' COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='自定义布局配置项';

