-- ----------------------------
-- Table structure for zp_user
-- ----------------------------
DROP TABLE IF EXISTS `zp_user`;
CREATE TABLE `zp_user` (
   `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
   `pid` int(11) DEFAULT '0' COMMENT '上级ID',
   `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
   `username` varchar(50) DEFAULT NULL COMMENT '用户名',
   `avatar` varchar(200) DEFAULT NULL COMMENT '头像',
   `pwd` varchar(32) DEFAULT NULL COMMENT '密码',
   `salt` varchar(6) DEFAULT NULL COMMENT '盐值',
   `balance` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '余额',
   `mobile` varchar(11) DEFAULT NULL COMMENT '手机号码',
   `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
   `realname` varchar(50) DEFAULT NULL COMMENT '真实姓名',
   `account` varchar(64) DEFAULT NULL COMMENT '支付宝账户',
   `company` varchar(50) DEFAULT NULL COMMENT '公司名称',
   `province_id` int(10) unsigned DEFAULT '0',
   `city_id` int(10) unsigned DEFAULT '0',
   `county_id` int(255) unsigned DEFAULT '0',
   `address` varchar(80) DEFAULT NULL COMMENT '地址',
   `is_rzbiz` tinyint(1) unsigned DEFAULT '0' COMMENT '认证，0未认证，1待审核，2审核，-1拒绝',
   `token` varchar(32) DEFAULT NULL COMMENT '用户登录后token',
   `acc_openid` varchar(64) DEFAULT NULL COMMENT '公众号用户openid',
   `openid` varchar(50) DEFAULT NULL COMMENT '微信openid',
   `unionid` varchar(50) DEFAULT NULL COMMENT 'unionid',
   `tt_openid` varchar(64) DEFAULT NULL COMMENT '头条用户openid',
   `r_nums` int(10) unsigned DEFAULT '0' COMMENT '当天已获取资源数量，SVIP方式',
   `site_uid` int(10) unsigned DEFAULT '0' COMMENT '代理ID',
   `status` tinyint(1) unsigned DEFAULT '1' COMMENT '状态，1正常，0禁用',
   `login_time` int(11) unsigned DEFAULT '0' COMMENT '登录时间',
   `ctime` int(11) unsigned DEFAULT '0' COMMENT '注册时间',
   `utime` int(11) unsigned DEFAULT '0' COMMENT '登录时间',
   `vid` int(11) DEFAULT '0' COMMENT '会员类型ID',
   `level` tinyint(4) DEFAULT '0' COMMENT '用户等级：0普通1会员2合伙人',
   `exp_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '会员过期时间',
   `bankname` varchar(64) DEFAULT NULL COMMENT '银行名称',
   `bankno` varchar(48) DEFAULT NULL COMMENT '银行账号',
   PRIMARY KEY (`id`),
   UNIQUE KEY `openid` (`openid`),
   KEY `idx_token` (`token`),
   KEY `idx_admin_id` (`admin_id`),
   KEY `idx_pid` (`pid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

-- ----------------------------
-- Table structure for zp_user_cash
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_cash`;
CREATE TABLE `zp_user_cash` (
    `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
    `admin_id` int(10) unsigned DEFAULT '0',
    `ordno` char(48) DEFAULT NULL COMMENT '提现订单号',
    `type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '方式:1=支付宝,2=微信,3=其他',
    `money` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '提现余额',
    `fee` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '手续费',
    `amount` decimal(11,2) unsigned DEFAULT '0.00' COMMENT '实际付款金额',
    `account` varchar(64) DEFAULT NULL COMMENT '支付宝账户名',
    `bankname` varchar(64) DEFAULT NULL COMMENT '银行名称',
    `realname` varchar(48) DEFAULT NULL COMMENT '真实姓名',
    `bankno` varchar(48) DEFAULT NULL COMMENT '银行账号',
    `image` varchar(128) DEFAULT NULL COMMENT '收款二维码',
    `remark` varchar(256) DEFAULT NULL COMMENT '备注',
    `package` varchar(256) DEFAULT NULL COMMENT '微信商家转账页面信息',
    `confirm` tinyint(1) unsigned DEFAULT '0' COMMENT '商家确认收款状态',
    `reason` varchar(256) DEFAULT NULL COMMENT '审核操作原因',
    `status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '审核状态:0=审核中,1=通过,-1=不通过,2=已打款(完成)',
    `uid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '申请提现用户',
    `utime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
    `ctime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '申请时间',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='提现明细';

-- ----------------------------
-- Table structure for zp_user_coll
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_coll`;
CREATE TABLE `zp_user_coll` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `uid` int(11) DEFAULT NULL,
    `rid` int(11) DEFAULT NULL COMMENT '资源id',
    `ctime` int(11) DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='收藏表';

-- ----------------------------
-- Table structure for zp_user_level
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_level`;
CREATE TABLE `zp_user_level` (
     `id` smallint(4) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
     `name` varchar(30) DEFAULT NULL COMMENT '头衔名称',
     `indexid` int(3) DEFAULT '0' COMMENT '排序',
     `min` int(5) DEFAULT '0' COMMENT '积分下限',
     `max` int(5) DEFAULT '0' COMMENT '积分上限',
     `status` tinyint(1) unsigned DEFAULT '1' COMMENT '状态，1启用，0禁用',
     PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='  用户等级表';


-- ----------------------------
-- Table structure for zp_user_qrcode
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_qrcode`;
CREATE TABLE `zp_user_qrcode` (
      `id` int(11) NOT NULL AUTO_INCREMENT,
      `uid` int(10) unsigned DEFAULT '0' COMMENT '用户ID',
      `ticket` varchar(128) DEFAULT NULL COMMENT '二维码的ticket',
      `key` varchar(48) DEFAULT NULL COMMENT '用户登录IP',
      `from_id` int(10) unsigned DEFAULT '0' COMMENT '分站ID',
      `rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID',
      `invite_uid` int(10) unsigned DEFAULT '0' COMMENT '邀请人ID',
      `utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
      `ctime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
      PRIMARY KEY (`id`),
      KEY `idx_key` (`key`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Table structure for zp_user_resource
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_resource`;
CREATE TABLE `zp_user_resource` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '代理ID',
    `rid` int(11) NOT NULL COMMENT '资源ID',
    `type` tinyint(4) unsigned DEFAULT '1' COMMENT '1购买，2任务获取，3会员获取',
    `uid` int(11) unsigned NOT NULL DEFAULT '0',
    `work_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '卡密资源ID',
    `ctime` int(11) NOT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_res` (`uid`,`rid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='我的资源';


-- ----------------------------
-- Table structure for zp_user_subscribe
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_subscribe`;
CREATE TABLE `zp_user_subscribe` (
     `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
     `admin_id` int(10) unsigned DEFAULT '0' COMMENT '代理商ID',
     `rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID',
     `name` varchar(32) DEFAULT NULL COMMENT '模板名称',
     `temp_id` varchar(64) DEFAULT NULL COMMENT '模板ID',
     `result` varchar(12) DEFAULT NULL COMMENT '订阅结果',
     `uid` int(11) unsigned DEFAULT '0' COMMENT '用户订阅',
     `ctime` int(11) unsigned DEFAULT '0',
     PRIMARY KEY (`id`),
     KEY `idx_uid` (`uid`),
     KEY `idx_where` (`temp_id`,`rid`,`uid`,`result`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='用户微信模板订阅消息结果';

-- ----------------------------
-- Table structure for zp_user_third
-- ----------------------------
DROP TABLE IF EXISTS `zp_user_third`;
CREATE TABLE `zp_user_third` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '用户ID',
     `type` tinyint(1) unsigned DEFAULT '1' COMMENT '第三方登录类型:1微信小程序,2微信公众号,3,抖音,4百度,5APP',
     `uid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关联用户表',
     `openid` varchar(50) DEFAULT NULL COMMENT '第三方openid',
     `session_key` varchar(50) DEFAULT NULL,
     `unionid` varchar(50) DEFAULT NULL,
     `avatar` varchar(256) DEFAULT NULL COMMENT '头像',
     `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
     `gender` smallint(1) unsigned NOT NULL DEFAULT '0' COMMENT '性别 0：未知、1：男、2：女',
     `language` varchar(50) DEFAULT NULL COMMENT '语言',
     `city` varchar(80) DEFAULT NULL COMMENT '城市',
     `province` varchar(80) DEFAULT NULL COMMENT '省',
     `country` varchar(80) DEFAULT NULL COMMENT '国家',
     `country_code` varchar(20) DEFAULT NULL COMMENT '手机号码国家编码',
     `mobile` varchar(20) DEFAULT NULL COMMENT '手机号码',
     `ctime` int(11) unsigned DEFAULT '0' COMMENT '创建时间',
     `utime` int(11) unsigned DEFAULT '0' COMMENT '更新时间',
     PRIMARY KEY (`id`) USING BTREE,
     KEY `idx_type` (`type`),
     KEY `idx_uid` (`uid`),
     KEY `idx_openid` (`openid`),
     KEY `idx_union` (`unionid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='第三方平台登录用户表';

-- ----------------------------
-- Table structure for zp_validate
-- ----------------------------
DROP TABLE IF EXISTS `zp_validate`;
CREATE TABLE `zp_validate` (
   `id` int(11) NOT NULL AUTO_INCREMENT,
   `mobile` varchar(15) DEFAULT NULL,
   `code` varchar(10) DEFAULT NULL COMMENT '验证码',
   `status` tinyint(2) unsigned DEFAULT '0' COMMENT '0未使用1已使用',
   `ctime` int(11) unsigned DEFAULT '0',
   PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='验证码表';

-- ----------------------------
-- Table structure for zp_versions
-- ----------------------------
DROP TABLE IF EXISTS `zp_versions`;
CREATE TABLE `zp_versions` (
   `id` int(11) NOT NULL AUTO_INCREMENT,
   `versions` varchar(64) DEFAULT NULL COMMENT '版本名称',
   `versions_nums` int(10) unsigned DEFAULT NULL COMMENT '实际版本号',
   `content` text COMMENT '更新说明',
   `package` varchar(128) DEFAULT NULL COMMENT '更新包地址',
   `vnums` varchar(32) DEFAULT NULL COMMENT '常规版本号',
   `ptime` int(11) unsigned DEFAULT '0' COMMENT '发布时间',
   `ctime` int(11) unsigned DEFAULT '0' COMMENT '更新时间',
   PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='版本信息';

INSERT INTO `zp_versions` VALUES ('1', 'v5.0.15', '5015', '本次更新需要先安装swoole_loader扩展，联系客服获取扩展 \n 1、新增：个人主体微信小程序虎皮椒微信支付\n 2、新增：用户提现支持新版商家转账功能 \n 3、新增：存储设置支持缩略图、图片水印功能\n 4、新增：系统更新日志、下载更新包功能\n 5、新增：资源管理支持资源复制功能\n 6、新增：代理分站支持生成卡密功能 7、新增：主站支持下发和控制分站生成卡密功能\n 8、新增：总站和代理的管理后台分离\n 9、新增：PC小程序支持文档直接下载功能\n 10、新增：代理分站支持开通时设置自动同步推广资源功能\n 11、新增：素材管理支持多文件上传和文件检索\n 12、新增：个人小程序支持过审模式\n 13、优化：系统架构优化，增强系统负载能力\n 14、优化：文档转发下载、在线预览显示文档名称\n 15、优化：PC端支持虎皮椒微信和支付宝扫码支付\n 16、优化：管理后台UI界面优化\n 17、优化：助力记录根据助力类型优化显示\n 18、优化：优化在线更新进度和更新流程\n 19、优化：权限管理使权限控制更细致\n 20、修复：老浏览器访问后台部分页面显示异常问题\n 21、修复：PC端显示代理分站设置的SVIP套餐问题\n 22、修复：分站海报左侧预览设置后没有实时显示\n 23、修复：分站推广海报生成缓存问题\n 24、修复：用户提现列表搜索功能异常\n 25、修复：腾讯云存储素材删除失败问题\n 温馨提示：本次更新微信小程序需要重新提交代码提审，PC端配置需要在后台点击垃圾桶图标清除缓存，定制版本的客户请勿更新', '', '5.0.15', '1734952138', '1743057617');

-- ----------------------------
-- Table structure for zp_video_course
-- ----------------------------
DROP TABLE IF EXISTS `zp_video_course`;
CREATE TABLE `zp_video_course` (
   `id` int(11) NOT NULL AUTO_INCREMENT,
   `title` varchar(150) DEFAULT NULL COMMENT '课程标题',
   `thumb` varchar(128) DEFAULT NULL COMMENT '封面图',
   `url` varchar(255) DEFAULT NULL COMMENT '课程地址',
   `desc` varchar(255) DEFAULT NULL COMMENT '简介',
   `rid` int(11) DEFAULT NULL COMMENT '资源ID',
   `times` varchar(24) DEFAULT NULL COMMENT '时长',
   `is_try` tinyint(1) DEFAULT '0' COMMENT '是否试看',
   `indexid` int(11) DEFAULT NULL COMMENT '排序',
   `ctime` int(11) DEFAULT NULL,
   PRIMARY KEY (`id`),
   KEY `idx_rid` (`rid`),
   KEY `union_whre` (`rid`,`indexid`,`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='视频课程';

-- ----------------------------
-- Records of zp_video_course
-- ----------------------------

-- ----------------------------
-- Table structure for zp_view_log
-- ----------------------------
DROP TABLE IF EXISTS `zp_view_log`;
CREATE TABLE `zp_view_log` (
       `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
       `admin_id` int(10) unsigned DEFAULT '0' COMMENT '所属代理ID',
       `rid` int(10) unsigned DEFAULT '0' COMMENT '资源ID',
       `type` tinyint(3) unsigned DEFAULT '0' COMMENT '1、视频章节，2音频章节，3小说章节',
       `cid` int(10) unsigned DEFAULT '0' COMMENT '章节ID关联章节表',
       `uid` int(10) unsigned DEFAULT '0' COMMENT '用户ID',
       `nums` int(10) unsigned DEFAULT '0' COMMENT '观看次数',
       `status` tinyint(3) unsigned DEFAULT '0' COMMENT '浏览状态，1浏览完成，0未浏览完',
       `utime` int(10) unsigned DEFAULT '0' COMMENT '更新时间',
       `ctime` int(10) unsigned DEFAULT '0' COMMENT '记录时间',
       PRIMARY KEY (`id`),
       KEY `idx_where` (`rid`,`type`,`cid`) USING BTREE,
       KEY `idx_rid` (`rid`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='章节播放记录';

-- ----------------------------
-- Table structure for zp_wechat_key
-- ----------------------------
DROP TABLE IF EXISTS `zp_wechat_key`;
CREATE TABLE `zp_wechat_key` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
     `name` varchar(258) DEFAULT NULL COMMENT '名称',
     `type` varchar(16) DEFAULT NULL COMMENT '消息类型：text,image,video,voice,news',
     `content` text COMMENT '消息内容',
     `status` tinyint(2) unsigned DEFAULT '1' COMMENT '状态：1启用：禁用',
     `utime` int(10) unsigned DEFAULT '0',
     `ctime` int(10) unsigned DEFAULT '0',
     PRIMARY KEY (`id`),
     KEY `idx_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='微信公众号关键字回复';

-- ----------------------------
-- Table structure for zp_wechat_rece
-- ----------------------------
DROP TABLE IF EXISTS `zp_wechat_rece`;
CREATE TABLE `zp_wechat_rece` (
      `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
      `type` varchar(16) DEFAULT NULL COMMENT '消息类型：text,image,video,voice,news',
      `content` text COMMENT '消息内容',
      `status` tinyint(2) unsigned DEFAULT '1' COMMENT '状态：1启用：禁用',
      `utime` int(10) unsigned DEFAULT '0',
      `ctime` int(10) unsigned DEFAULT '0',
      PRIMARY KEY (`id`),
      KEY `idx_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='微信公众号收到消息回复';

-- ----------------------------
-- Table structure for zp_wechat_sub
-- ----------------------------
DROP TABLE IF EXISTS `zp_wechat_sub`;
CREATE TABLE `zp_wechat_sub` (
     `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
     `type` varchar(16) DEFAULT NULL COMMENT '消息类型：text,image,video,voice,news',
     `content` text COMMENT '消息内容',
     `status` tinyint(2) unsigned DEFAULT '1' COMMENT '状态：1启用：禁用',
     `utime` int(10) unsigned DEFAULT '0',
     `ctime` int(10) unsigned DEFAULT '0',
     PRIMARY KEY (`id`),
     KEY `idx_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='微信公众号关注回复';